SELECT 
FROM attachment
WHERE org_id = #{orgId}
  AND request_key = #{requestKey}

SELECT 
FROM attachment
WHERE activity_id = #{activityId}
  AND expense_id = #{expenseId}
  AND deleted_at IS NULL
ORDER BY created_at DESC, id DESC

SELECT 
FROM attachment
WHERE activity_id = #{activityId}
  AND task_id = #{taskId}
  AND deleted_at IS NULL
ORDER BY created_at DESC, id DESC

SELECT COUNT(*)
FROM attachment
WHERE stored_name = #{storedName}
